query:
-- Get Guys on Ice project ID
SET @guys_id = (SELECT id FROM projects WHERE title = 'Guys on Ice' LIMIT 1);

-- Add tags for Guys on Ice
INSERT INTO projectTags (projectId, tagId)
SELECT @guys_id, id FROM tags WHERE name IN ('Musical Comedy', '2025', 'Regional Theatre', 'Wisconsin', 'Ice Fishing', 'Comedy')
ON DUPLICATE KEY UPDATE projectId = projectId;

